{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyonthreshold.org/incident-ready/schema/0.1.0/incident-report.schema.json",
  "title": "Incident Ready report",
  "description": "Experimental, versioned envelope for regulator incident reports. This is not a secure transport or legal reporting standard.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "report",
    "incident",
    "timeline",
    "affected_system",
    "impacts",
    "safeguards",
    "response",
    "evidence",
    "handling"
  ],
  "properties": {
    "schema_version": { "const": "0.1.0" },
    "report": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "report_id",
        "incident_id",
        "type",
        "created_at",
        "reporting_organization",
        "contact_role",
        "detection_at",
        "awareness_at",
        "initial_notification_due_at",
        "threshold_assessment",
        "supersedes_report_id",
        "changed_fields",
        "completion"
      ],
      "properties": {
        "report_id": { "type": "string", "format": "uuid" },
        "incident_id": { "type": "string", "format": "uuid" },
        "type": { "enum": ["initial", "update", "correction", "final"] },
        "created_at": { "type": "string", "format": "date-time" },
        "reporting_organization": { "type": "string", "minLength": 1, "maxLength": 300 },
        "contact_role": { "type": "string", "minLength": 1, "maxLength": 300 },
        "detection_at": { "type": "string", "format": "date-time" },
        "awareness_at": { "type": "string", "format": "date-time" },
        "initial_notification_due_at": { "type": "string", "format": "date-time" },
        "threshold_assessment": {
          "type": "object",
          "additionalProperties": false,
          "required": ["status", "rationale", "review_by"],
          "properties": {
            "status": { "enum": ["reportable", "not_reportable", "undetermined"] },
            "rationale": { "type": "string", "minLength": 1, "maxLength": 5000 },
            "review_by": { "type": "string", "format": "date-time" }
          }
        },
        "supersedes_report_id": { "type": ["string", "null"], "format": "uuid" },
        "changed_fields": {
          "type": "array",
          "items": { "type": "string", "pattern": "^/[A-Za-z0-9_~/-]+$" },
          "uniqueItems": true,
          "maxItems": 200
        },
        "completion": {
          "type": "object",
          "additionalProperties": false,
          "required": ["root_cause_status", "open_questions"],
          "properties": {
            "root_cause_status": { "enum": ["not_started", "preliminary", "established", "not_applicable"] },
            "open_questions": {
              "type": "array",
              "items": { "type": "string", "minLength": 1, "maxLength": 2000 },
              "maxItems": 100
            }
          }
        }
      }
    },
    "incident": {
      "type": "object",
      "additionalProperties": false,
      "required": ["title", "what_happened", "observed_behavior", "incident_class", "harm_realization", "potential_consequences", "geographic_scope"],
      "properties": {
        "title": { "type": "string", "minLength": 1, "maxLength": 300 },
        "what_happened": { "type": "string", "minLength": 1, "maxLength": 15000 },
        "observed_behavior": {
          "type": "array",
          "minItems": 1,
          "items": { "type": "string", "minLength": 1, "maxLength": 3000 },
          "maxItems": 100
        },
        "incident_class": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "enum": [
              "loss_of_control",
              "safeguard_failure",
              "deceptive_or_concealed_behavior",
              "unauthorized_self_replication",
              "unauthorized_resource_acquisition",
              "dangerous_capability_elicitation",
              "critical_system_disruption",
              "physical_harm",
              "cybersecurity",
              "biological_or_chemical",
              "privacy_or_data_exposure",
              "large_scale_manipulation",
              "other"
            ]
          },
          "maxItems": 20
        },
        "harm_realization": { "enum": ["actual", "potential_only", "both", "undetermined"] },
        "potential_consequences": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["description", "likelihood", "severity", "basis"],
            "properties": {
              "description": { "type": "string", "minLength": 1, "maxLength": 3000 },
              "likelihood": { "enum": ["low", "medium", "high", "unknown"] },
              "severity": { "enum": ["limited", "serious", "catastrophic", "unknown"] },
              "basis": { "type": "string", "minLength": 1, "maxLength": 3000 }
            }
          },
          "maxItems": 50
        },
        "geographic_scope": { "enum": ["local", "national", "multinational", "global", "unknown"] }
      }
    },
    "timeline": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["occurred_at", "event", "source", "confidence"],
        "properties": {
          "occurred_at": { "type": "string", "format": "date-time" },
          "event": { "type": "string", "minLength": 1, "maxLength": 3000 },
          "source": { "type": "string", "minLength": 1, "maxLength": 1000 },
          "confidence": { "enum": ["confirmed", "reported", "inferred", "uncertain"] }
        }
      },
      "maxItems": 500
    },
    "affected_system": {
      "type": "object",
      "additionalProperties": false,
      "required": ["internal_model_id", "model_version", "deployment", "lifecycle_stage", "system_components", "tools_and_permissions", "external_dependencies", "deployment_scale"],
      "properties": {
        "internal_model_id": { "type": "string", "minLength": 1, "maxLength": 500 },
        "model_version": { "type": "string", "minLength": 1, "maxLength": 500 },
        "deployment": { "type": "string", "minLength": 1, "maxLength": 500 },
        "lifecycle_stage": { "enum": ["development", "evaluation", "staged_deployment", "production", "post_deployment", "unknown"] },
        "system_components": {
          "type": "array",
          "items": { "type": "string", "minLength": 1, "maxLength": 1000 },
          "maxItems": 100
        },
        "tools_and_permissions": {
          "type": "array",
          "items": { "type": "string", "minLength": 1, "maxLength": 1000 },
          "maxItems": 100
        },
        "external_dependencies": {
          "type": "array",
          "items": { "type": "string", "minLength": 1, "maxLength": 1000 },
          "maxItems": 100
        },
        "deployment_scale": {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "unit", "as_of"],
          "properties": {
            "value": { "type": ["number", "null"], "minimum": 0 },
            "unit": { "enum": ["users", "sessions", "agent_instances", "organizations", "other", "unknown"] },
            "as_of": { "type": "string", "format": "date-time" }
          }
        }
      }
    },
    "impacts": {
      "type": "object",
      "additionalProperties": false,
      "required": ["actual", "assessment_status"],
      "properties": {
        "assessment_status": { "enum": ["preliminary", "complete", "undetermined"] },
        "actual": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["category", "description", "severity", "affected_count", "affected_count_unit", "basis"],
            "properties": {
              "category": { "enum": ["human_safety", "physical_assets", "digital_systems", "privacy", "financial", "rights", "environment", "public_services", "other"] },
              "description": { "type": "string", "minLength": 1, "maxLength": 5000 },
              "severity": { "enum": ["limited", "serious", "catastrophic", "unknown"] },
              "affected_count": { "type": ["number", "null"], "minimum": 0 },
              "affected_count_unit": { "enum": ["people", "accounts", "systems", "organizations", "transactions", "other", "unknown"] },
              "basis": { "type": "string", "minLength": 1, "maxLength": 3000 }
            }
          },
          "maxItems": 100
        }
      }
    },
    "safeguards": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["safeguard_id", "name", "intended_risk_control", "outcome", "observed_behavior", "evidence_refs"],
        "properties": {
          "safeguard_id": { "type": "string", "minLength": 1, "maxLength": 200 },
          "name": { "type": "string", "minLength": 1, "maxLength": 500 },
          "intended_risk_control": { "type": "string", "minLength": 1, "maxLength": 3000 },
          "outcome": { "enum": ["prevented", "reduced", "failed", "bypassed", "not_triggered", "not_applicable", "unknown"] },
          "observed_behavior": { "type": "string", "minLength": 1, "maxLength": 5000 },
          "evidence_refs": {
            "type": "array",
            "items": { "type": "string", "minLength": 1, "maxLength": 200 },
            "uniqueItems": true,
            "maxItems": 100
          }
        }
      },
      "maxItems": 100
    },
    "response": {
      "type": "object",
      "additionalProperties": false,
      "required": ["containment_status", "actions", "recurrence_possible", "other_parties_notified", "corrective_actions"],
      "properties": {
        "containment_status": { "enum": ["contained", "partially_contained", "not_contained", "unknown"] },
        "actions": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["action", "status", "occurred_at", "effect"],
            "properties": {
              "action": { "type": "string", "minLength": 1, "maxLength": 3000 },
              "status": { "enum": ["planned", "in_progress", "completed", "failed", "unknown"] },
              "occurred_at": { "type": ["string", "null"], "format": "date-time" },
              "effect": { "type": "string", "minLength": 1, "maxLength": 3000 }
            }
          },
          "maxItems": 100
        },
        "recurrence_possible": { "enum": ["yes", "no", "unknown"] },
        "other_parties_notified": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["party_role", "notified_at", "purpose"],
            "properties": {
              "party_role": { "type": "string", "minLength": 1, "maxLength": 500 },
              "notified_at": { "type": "string", "format": "date-time" },
              "purpose": { "type": "string", "minLength": 1, "maxLength": 2000 }
            }
          },
          "maxItems": 100
        },
        "corrective_actions": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["action_id", "description", "owner_role", "status", "due_at", "verification_method"],
            "properties": {
              "action_id": { "type": "string", "minLength": 1, "maxLength": 200 },
              "description": { "type": "string", "minLength": 1, "maxLength": 5000 },
              "owner_role": { "type": "string", "minLength": 1, "maxLength": 500 },
              "status": { "enum": ["proposed", "accepted", "in_progress", "completed", "verified", "rejected"] },
              "due_at": { "type": ["string", "null"], "format": "date-time" },
              "verification_method": { "type": "string", "minLength": 1, "maxLength": 3000 }
            }
          },
          "maxItems": 100
        }
      }
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["evidence_id", "description", "reference", "collected_at", "integrity", "access_restriction"],
        "properties": {
          "evidence_id": { "type": "string", "minLength": 1, "maxLength": 200 },
          "description": { "type": "string", "minLength": 1, "maxLength": 3000 },
          "reference": { "type": "string", "minLength": 1, "maxLength": 2000, "description": "Opaque internal reference, not an embedded payload." },
          "collected_at": { "type": "string", "format": "date-time" },
          "integrity": {
            "type": "object",
            "additionalProperties": false,
            "required": ["algorithm", "digest"],
            "properties": {
              "algorithm": { "const": "sha256" },
              "digest": { "type": "string", "pattern": "^[0-9a-f]{64}$" }
            }
          },
          "access_restriction": { "enum": ["regulator_only", "restricted_regulator_team", "releasable_with_redaction"] }
        }
      },
      "maxItems": 500
    },
    "handling": {
      "type": "object",
      "additionalProperties": false,
      "required": ["distribution", "sensitivities", "public_release", "retention_class", "contact_instructions"],
      "properties": {
        "distribution": { "enum": ["regulator_only", "restricted_regulator_team", "releasable_with_redaction"] },
        "sensitivities": {
          "type": "array",
          "uniqueItems": true,
          "items": { "enum": ["personal_data", "trade_secret", "security_sensitive", "third_party_confidential", "legally_privileged", "reporter_protection", "none"] },
          "maxItems": 20
        },
        "public_release": {
          "type": "object",
          "additionalProperties": false,
          "required": ["permitted", "conditions"],
          "properties": {
            "permitted": { "type": "boolean" },
            "conditions": { "type": "string", "minLength": 1, "maxLength": 5000 }
          }
        }
      }
    },
    "retention_class": { "type": "string", "minLength": 1, "maxLength": 200 },
    "contact_instructions": { "type": "string", "minLength": 1, "maxLength": 2000 }
  }
}

