        "array": lambda item: isinstance(item, list),
        "string": lambda item: isinstance(item, str),
        "number": lambda item: isinstance(item, (int, float)) and not isinstance(item, bool),
        "integer": lambda item: isinstance(item, int) and not isinstance(item, bool),
        "boolean": lambda item: isinstance(item, bool),
        "null": lambda item: item is None,
    }
    return checks[expected](value)


def validate_against_schema(value: Any, schema: dict[str, Any], path: str = "$") -> list[str]:
    """Validate the limited keyword subset used in incident-report.schema.json."""
    errors: list[str] = []
    if "const" in schema and value != schema["const"]:
        errors.append(f"{path}: expected constant {schema['const']!r}")
    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: {value!r} is not an allowed value")

    expected_type = schema.get("type")
    if expected_type:
        allowed = expected_type if isinstance(expected_type, list) else [expected_type]
        if not any(check_type(value, item) for item in allowed):
            errors.append(f"{path}: expected type {expected_type}, got {type(value).__name__}")
            return errors

    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(f"{path}: string is shorter than {schema['minLength']}")
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append(f"{path}: string exceeds {schema['maxLength']} characters")
        if "pattern" in schema and not re.search(schema["pattern"], value):
            errors.append(f"{path}: string does not match {schema['pattern']}")
        if schema.get("format") == "uuid" and not UUID_RE.fullmatch(value):
            errors.append(f"{path}: invalid UUID")
        if schema.get("format") == "date-time":
            try:
                parse_datetime(value)
            except (ValueError, TypeError):
                errors.append(f"{path}: invalid timezone-aware RFC 3339 timestamp")

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append(f"{path}: value is below minimum {schema['minimum']}")

    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value:
                errors.append(f"{path}: missing required property {key!r}")
        properties = schema.get("properties", {})
        if schema.get("additionalProperties") is False:
            for key in value:
                if key not in properties:
                    errors.append(f"{path}: unexpected property {key!r}")
        for key, child in value.items():
            if key in properties:
                errors.extend(validate_against_schema(child, properties[key], f"{path}.{key}"))

    if isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append(f"{path}: fewer than {schema['minItems']} items")
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            errors.append(f"{path}: more than {schema['maxItems']} items")
        if schema.get("uniqueItems"):
            for index, item in enumerate(value):
                if item in value[:index]:
                    errors.append(f"{path}[{index}]: duplicate array item")
        if "items" in schema:
            for index, item in enumerate(value):
                errors.extend(validate_against_schema(item, schema["items"], f"{path}[{index}]"))
    return errors


def validate_semantics(document: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    try:
        report = document["report"]
        incident = document["incident"]
        impacts = document["impacts"]
        handling = document["handling"]
        evidence = document["evidence"]
        safeguards = document["safeguards"]
        timeline = document["timeline"]
    except (KeyError, TypeError):
        return errors  # Structural validation already reports missing sections.

    try:
        detection = parse_datetime(report["detection_at"])
        awareness = parse_datetime(report["awareness_at"])
        created = parse_datetime(report["created_at"])
        due = parse_datetime(report["initial_notification_due_at"])
        if not detection <= awareness <= created:
            errors.append("report: expected detection_at <= awareness_at <= created_at")
        if due < created:
            errors.append("report: initial notification deadline precedes report creation")
    except (KeyError, ValueError, TypeError):
        pass

    try:
        timestamps = [parse_datetime(event["occurred_at"]) for event in timeline]
        if timestamps != sorted(timestamps):
            errors.append("timeline: events must be in nondecreasing chronological order")
    except (KeyError, ValueError, TypeError):
        pass

    report_type = report.get("type")
    supersedes = report.get("supersedes_report_id")
    changed = report.get("changed_fields", [])
    if report_type == "initial" and (supersedes is not None or changed):
        errors.append("report: initial reports cannot supersede a report or list changed fields")
    if report_type in {"update", "correction", "final"} and not supersedes:
        errors.append("report: non-initial reports must identify the report they supersede")
    if report_type in {"update", "correction", "final"} and not changed:
        errors.append("report: non-initial reports must enumerate changed fields")
    if supersedes and supersedes == report.get("report_id"):
        errors.append("report: a report cannot supersede itself")

    realization = incident.get("harm_realization")
    actual = impacts.get("actual", [])
    if realization in {"actual", "both"} and not actual:
        errors.append("impacts: actual/both harm requires at least one actual impact")
    if realization == "potential_only" and actual:
        errors.append("impacts: potential_only harm cannot contain actual impacts")

    evidence_ids = [item.get("evidence_id") for item in evidence if isinstance(item, dict)]
    if len(evidence_ids) != len(set(evidence_ids)):
        errors.append("evidence: evidence_id values must be unique")
    for safeguard in safeguards:
        for ref in safeguard.get("evidence_refs", []):
            if ref not in evidence_ids:
                errors.append(f"safeguards: unknown evidence reference {ref!r}")

    sensitivities = handling.get("sensitivities", [])
    if "none" in sensitivities and len(sensitivities) != 1:
        errors.append("handling: 'none' cannot be combined with other sensitivities")
    if handling.get("public_release", {}).get("permitted") and handling.get("distribution") != "releasable_with_redaction":
        errors.append("handling: public release requires releasable_with_redaction distribution")
    return errors


def validate_document(document: Any, schema: dict[str, Any]) -> list[str]:
    errors = validate_against_schema(document, schema)
    if isinstance(document, dict):
        errors.extend(validate_semantics(document))
    return errors


def validate_chain(documents: list[dict[str, Any]]) -> list[str]:
    errors: list[str] = []
    by_id: dict[str, dict[str, Any]] = {}
    for document in documents:
        report_id = document.get("report", {}).get("report_id")
        if report_id in by_id:
            errors.append(f"chain: duplicate report_id {report_id}")
        by_id[report_id] = document
    for document in documents:
        report = document.get("report", {})
        parent_id = report.get("supersedes_report_id")
        if not parent_id or parent_id not in by_id:
            continue
        parent = by_id[parent_id]["report"]
        if parent.get("incident_id") != report.get("incident_id"):
            errors.append(f"chain: {report.get('report_id')} changes incident_id")
        try:
            if parse_datetime(report["created_at"]) < parse_datetime(parent["created_at"]):
                errors.append(f"chain: {report.get('report_id')} predates its parent")
        except (KeyError, ValueError, TypeError):
            pass
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("reports", nargs="+", type=Path)
    parser.add_argument("--full-schema", action="store_true", help="Also validate with optional jsonschema package")
    args = parser.parse_args()
    schema = json.loads(SCHEMA_PATH.read_text())
    documents: list[dict[str, Any]] = []
    failed = False
    for path in args.reports:
        try:
            document = json.loads(path.read_text())
            errors = validate_document(document, schema)
            if args.full_schema:
                try:
                    import jsonschema  # type: ignore
                except ImportError:
                    errors.append("optional jsonschema package is not installed")
                else:
                    validator = jsonschema.Draft202012Validator(schema, format_checker=jsonschema.FormatChecker())
                    errors.extend(f"jsonschema: {error.message}" for error in validator.iter_errors(document))
            documents.append(document)
        except (OSError, json.JSONDecodeError) as exc:
            errors = [str(exc)]
        if errors:
            failed = True
            print(f"FAIL {path}")
            for error in errors:
                print(f"  - {error}")
        else:
            print(f"PASS {path}")
    chain_errors = validate_chain(documents)
    if chain_errors:
        failed = True
        for error in chain_errors:
            print(f"  - {error}")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import copy
import json
import unittest
from pathlib import Path

from validate_reports import (
    PROJECT_DIR,
    SCHEMA_PATH,
    validate_against_schema,
    validate_chain,
    validate_document,
)

EXAMPLES = PROJECT_DIR / "examples"


def load(name: str):
    return json.loads((EXAMPLES / name).read_text())


def assert_required_properties_exist(node, path="$"):
    """Return schema-authoring errors for missing property definitions."""
    errors = []
    if not isinstance(node, dict):
        return errors
    if node.get("type") == "object":
        properties = node.get("properties", {})
        for required in node.get("required", []):
            if required not in properties:
                errors.append(f"{path}: required property {required!r} has no definition")
        for key, child in properties.items():
            errors.extend(assert_required_properties_exist(child, f"{path}.{key}"))
    if "items" in node:
        errors.extend(assert_required_properties_exist(node["items"], f"{path}[]"))
    return errors


class ReportValidationTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.schema = json.loads(SCHEMA_PATH.read_text())
        cls.initial = load("initial-near-miss.json")
        cls.final = load("final-update.json")

    def test_schema_required_properties_are_defined(self):
        self.assertEqual([], assert_required_properties_exist(self.schema))

    def test_valid_examples(self):
        self.assertEqual([], validate_document(self.initial, self.schema))
        self.assertEqual([], validate_document(self.final, self.schema))

    def test_valid_update_chain(self):
        self.assertEqual([], validate_chain([self.initial, self.final]))

    def test_invalid_fixture_is_rejected_for_multiple_reasons(self):
        errors = validate_document(load("invalid-report.json"), self.schema)
        joined = "\n".join(errors)
        self.assertIn("invalid UUID", joined)
        self.assertIn("detection_at <= awareness_at <= created_at", joined)
        self.assertIn("must identify the report they supersede", joined)
        self.assertIn("actual/both harm requires", joined)
        self.assertIn("unknown evidence reference", joined)
        self.assertIn("cannot be combined", joined)
        self.assertIn("public release requires", joined)

    def test_zero_is_not_unknown(self):
        changed = copy.deepcopy(self.initial)
        changed["affected_system"]["deployment_scale"]["value"] = 0
        changed["affected_system"]["deployment_scale"]["unit"] = "unknown"
        errors = validate_document(changed, self.schema)
        self.assertEqual([], errors, "zero remains a numeric value; unit communicates interpretation")

    def test_actual_impact_cannot_be_potential_only(self):
        changed = copy.deepcopy(self.initial)
        changed["incident"]["harm_realization"] = "potential_only"
        changed["impacts"]["actual"] = [{
            "category": "financial",
            "description": "Synthetic loss.",
            "severity": "limited",
            "affected_count": 1,
            "affected_count_unit": "transactions",
            "basis": "Test fixture."
        }]
        self.assertIn("potential_only harm cannot contain actual impacts", validate_document(changed, self.schema))

    def test_chain_cannot_change_incident_id(self):
        changed = copy.deepcopy(self.final)
        changed["report"]["incident_id"] = "10000000-0000-4000-8000-000000000011"
        errors = validate_chain([self.initial, changed])
        self.assertTrue(any("changes incident_id" in error for error in errors))

    def test_public_view_uses_allowlist_and_has_no_identifiers(self):
        public = load("public-view.json")
        allowed = {
            "view_version", "derived_from_report_id", "synthetic", "published_at",
            "review_status", "summary", "harm_realization", "actual_impacts",
            "safeguard_outcomes", "corrective_theme", "limitations"
        }
        self.assertEqual(allowed, set(public))
        serialized = json.dumps(public)
        for forbidden in ["synthetic-model-alpha", "synthetic-build-7", "E-001", "synthetic://", "duty lead"]:
            self.assertNotIn(forbidden, serialized)
        self.assertIsNone(public["published_at"])
        self.assertEqual("not_approved_for_release", public["review_status"])

    def test_unexpected_property_is_rejected(self):
        changed = copy.deepcopy(self.initial)
        changed["raw_sensitive_logs"] = "not allowed"
        errors = validate_against_schema(changed, self.schema)
        self.assertTrue(any("unexpected property 'raw_sensitive_logs'" in error for error in errors))


if __name__ == "__main__":
    unittest.main()
